import XCTest
@testable import FlagshipCore

/// Pins the Swift port to packages/protocol/test-vectors/pq-authority/vectors.json (generated by
/// tools/pq-authority-vectors.ts): the rotation's and grants' canonical bytes, every rotation and
/// grant case, and the old root's companion re-signed byte for byte.
final class PqAuthorityVectorTests: XCTestCase {
    private func vectors() throws -> [String: Any] {
        var dir = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        for _ in 0..<14 {
            let url = dir.appendingPathComponent("packages/protocol/test-vectors/pq-authority/vectors.json")
            if FileManager.default.fileExists(atPath: url.path) {
                return try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
            }
            dir = dir.deletingLastPathComponent()
        }
        throw XCTSkip("pq-authority vectors not found above \(#filePath)")
    }

    private func i64(_ v: Any?) -> Int64 { (v as! NSNumber).int64Value }

    private func rotation(_ v: [String: Any]) -> AdminRootRotation {
        let f = (v["rotation"] as! [String: Any])["fields"] as! [String: Any]
        return AdminRootRotation(username: f["username"] as! String, oldAdminRootPubHex: f["oldAdminRootPubHex"] as! String,
                                 newAdminRootPubHex: f["newAdminRootPubHex"] as! String, issuedAt: i64(f["issuedAt"]))
    }

    private func grant(_ f: [String: Any]) -> DeviceCapabilityGrantEnvelope {
        DeviceCapabilityGrantEnvelope(grantId: f["grantId"] as! String, username: f["username"] as! String, deviceId: f["deviceId"] as! String,
                                      devicePubKeyHex: f["devicePubKeyHex"] as! String, scopes: f["scopes"] as! [String],
                                      issuedAt: i64(f["issuedAt"]), expiresAt: i64(f["expiresAt"]))
    }

    private func verified(_ v: [String: Any], _ name: Any?) throws -> VerifiedPqKeyBinding? {
        guard let name = name as? String else { return nil }
        let w = (v["bindings"] as! [String: Any])[name] as! [String: Any]
        return try PqTrust.verifyPqKeyBinding(w as Any?, PqBindingExpectation(
            role: w["role"] as! String, subjectId: w["subjectId"] as! String, ed25519PubHex: w["ed25519PubHex"] as! String, now: i64(v["now"])))
    }

    private func policy(_ p: Any?) -> PolicyState {
        let p = p as! [String: Any]
        var s = AssurancePolicy.legacyState(PolicyScope(kind: .installation, id: "home.alice.flagship.services"))
        s.profile = AssuranceProfile(rawValue: p["profile"] as! String)!
        s.rollout = RolloutState(rawValue: p["rollout"] as! String)!
        return s
    }

    private func code(_ f: () throws -> Void) -> String {
        do { try f(); return "ok" } catch let e as PqTrustError { return e.code } catch { return "other:\(error)" }
    }

    func testCanonicalBytes() throws {
        let v = try vectors()
        let rot = v["rotation"] as! [String: Any]
        let nb = (v["bindings"] as! [String: Any])["newRoot"] as! [String: Any]
        let kid = PqAuthorityRecords.bindingKeyIdHex(ed25519PubHex: nb["ed25519PubHex"] as! String, mldsaPubHex: nb["mldsaPubHex"] as! String)
        XCTAssertEqual(kid, rot["newRootKeyId"] as? String)
        XCTAssertEqual(String(decoding: try PqAuthorityRecords.canonicalRotationV2(rotation(v), newRootKeyIdHex: kid), as: UTF8.self), rot["canonical"] as? String)
        XCTAssertThrowsError(try PqAuthorityRecords.canonicalRotationV2(rotation(v), newRootKeyIdHex: String(repeating: "AA", count: 32)))
        for k in ["admin", "member"] {
            let g = (v["grants"] as! [String: Any])[k] as! [String: Any]
            XCTAssertEqual(String(decoding: grant(g["fields"] as! [String: Any]).canonicalBytes(), as: UTF8.self), g["canonical"] as? String)
        }
    }

    func testCompanionResignsByteForByte() throws {
        let v = try vectors()
        let signer = (v["signers"] as! [[String: Any]]).first { $0["name"] as? String == "oldRoot" }!
        let secret = PqBin.unhex(signer["edSeedHex"] as! String)! + PqBin.unhex(signer["mldsaSeedHex"] as! String)!
        let nb = try PqTrust.pqKeyBindingFromWire((v["bindings"] as! [String: Any])["newRoot"])
        let c = try PqAuthorityRecords.signRotation(rotation(v), newRootBinding: nb) { purpose, payload in
            try PqHybrid.hybridSign(secretKey: secret, purpose: purpose, payload: payload, deterministic: true)
        }
        let want = ((v["rotation"] as! [String: Any])["pq"] as! [String: Any])["signature"] as! [String: Any]
        XCTAssertEqual(String(c.signature.signature.dropFirst(128)), String((want["signature"] as! String).dropFirst(128)))
        XCTAssertEqual(c.newRootBinding, nb)
        let admin = (v["grants"] as! [String: Any])["admin"] as! [String: Any]
        let gs = try PqAuthorityRecords.signGrant(grant(admin["fields"] as! [String: Any])) { purpose, payload in
            try PqHybrid.hybridSign(secretKey: secret, purpose: purpose, payload: payload, deterministic: true)
        }
        XCTAssertEqual(String(gs.signature.dropFirst(128)), String(((admin["pq"] as! [String: Any])["signature"] as! String).dropFirst(128)))
    }

    func testRotationCases() throws {
        let v = try vectors()
        let r = rotation(v)
        let newMl = ((v["bindings"] as! [String: Any])["newRoot"] as! [String: Any])["mldsaPubHex"] as? String
        for c in v["rotationCases"] as! [[String: Any]] {
            let old = try verified(v, c["oldRootBinding"])
            var got: String?
            let out = code { got = try PqAuthorityRecords.verifyRotation(r, pq: c["pq"], oldRootBinding: old, policy: policy(c["policy"]), now: i64(v["now"])).mldsaPubHex }
            let expect = c["expect"] as! [String: Any]
            if expect["ok"] as? Bool == true {
                XCTAssertEqual(out, "ok", c["name"] as! String)
                XCTAssertEqual(got, newMl)
            } else {
                XCTAssertEqual(out, expect["code"] as? String, c["name"] as! String)
            }
        }
    }

    func testGrantCases() throws {
        let v = try vectors()
        let bindings = v["bindings"] as! [String: Any]
        for c in v["grantCases"] as! [[String: Any]] {
            let signerPub = (bindings[c["signer"] as! String] as! [String: Any])["ed25519PubHex"] as! String
            let b = try verified(v, c["signerBinding"])
            let out = code { try PqAuthorityRecords.verifyGrant(grant(c["grant"] as! [String: Any]), pq: c["pq"], signerPubHex: signerPub,
                                                                signerBinding: b, policy: policy(c["policy"])) }
            let expect = c["expect"] as! [String: Any]
            let want = expect["ok"] as? Bool == true ? "ok" : (expect["code"] as? String ?? "")
            XCTAssertEqual(out, want, c["name"] as! String)
        }
    }
}
